import React, { useState, KeyboardEvent, useRef, useEffect } from 'react';
import { ArrowRight, Loader2 } from 'lucide-react';

interface FloatingInputProps {
  onSubmit: (text: string) => void;
  isLoading: boolean;
}

export const FloatingInput: React.FC<FloatingInputProps> = ({ onSubmit, isLoading }) => {
  const [text, setText] = useState('');
  const [isFocused, setIsFocused] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const handleSubmit = () => {
    if (isLoading || !text.trim()) return;
    onSubmit(text);
    setText('');
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 200)}px`;
    }
  }, [text]);

  return (
    <div className="w-full max-w-2xl mx-auto">
      <div 
        className={`
          relative border-b transition-all duration-500 ease-out
          ${isFocused ? 'border-sage' : 'border-border'}
          ${isLoading ? 'opacity-50 cursor-not-allowed' : ''}
        `}
      >
        <textarea
          ref={textareaRef}
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={handleKeyDown}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          placeholder="Describe your use case..."
          className="w-full bg-transparent text-text placeholder-muted/50 px-0 py-4 text-xl sm:text-2xl font-sans font-light resize-none focus:outline-none max-h-[300px] overflow-y-auto"
          rows={1}
          disabled={isLoading}
        />

        <div className="absolute right-0 bottom-4">
          <button
            onClick={handleSubmit}
            disabled={isLoading || !text.trim()}
            className={`
              flex items-center gap-2 text-xs uppercase tracking-widest font-semibold transition-all duration-300
              ${text.trim() && !isLoading ? 'text-sage hover:text-white translate-x-0' : 'text-border cursor-default translate-x-2 opacity-0'}
            `}
          >
            {isLoading ? (
              <span className="flex items-center gap-2">Processing <Loader2 size={12} className="animate-spin"/></span>
            ) : (
              <span className="flex items-center gap-2">Initialize <ArrowRight size={12} /></span>
            )}
          </button>
        </div>
      </div>

      {/* Helper text appearing only when focused or text present to keep it minimal */}
      <div className={`mt-4 transition-opacity duration-500 ${isFocused || text ? 'opacity-100' : 'opacity-0'}`}>
         <p className="text-xs text-muted font-sans">
           Press <span className="text-sage">Enter</span> to generate. Shift + Enter for new line.
         </p>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { ChevronDown, Check } from 'lucide-react';
import { TargetModel, ModelBrand, ModelMode } from '../types';
import { TARGET_MODELS } from '../constants';

interface ModelSelectorProps {
  selectedModel: TargetModel;
  onSelect: (model: TargetModel) => void;
}

const BRANDS: ModelBrand[] = ['ChatGPT', 'Gemini', 'Copilot', 'Claude'];

export const ModelSelector: React.FC<ModelSelectorProps> = ({ selectedModel, onSelect }) => {
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isAdvancedOpen, setIsAdvancedOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const advancedRef = useRef<HTMLDivElement>(null);

  // Group models for Advanced View
  const groupedModels = useMemo(() => {
    // Default to chat mode for simplicity in the list, or show all
    const groups: Record<string, TargetModel[]> = {};
    TARGET_MODELS.forEach(model => {
      if (!groups[model.provider]) groups[model.provider] = [];
      groups[model.provider].push(model);
    });
    return groups;
  }, []);

  const handleBrandSelect = (brand: ModelBrand) => {
    const defaultModel = TARGET_MODELS.find(m => m.brand === brand && m.isDefault);
    if (defaultModel) {
      onSelect(defaultModel);
    }
    setIsDropdownOpen(false);
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
      if (advancedRef.current && !advancedRef.current.contains(event.target as Node)) {
        setIsAdvancedOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div className="flex items-center space-x-6">

      {/* 1. SIMPLE DROPDOWN */}
      <div className="relative" ref={dropdownRef}>
        <button
            onClick={() => setIsDropdownOpen(!isDropdownOpen)}
            className="group flex items-center space-x-2 text-xs uppercase tracking-widest font-medium text-muted hover:text-text transition-colors"
        >
            <span>Target: <span className="text-sage border-b border-sage/30 pb-0.5">{selectedModel.brand === 'Other' ? selectedModel.name : selectedModel.brand}</span></span>
        </button>

        {isDropdownOpen && (
          <div className="absolute top-full right-0 mt-4 w-48 bg-background border border-border shadow-2xl z-50 animate-in fade-in slide-in-from-top-2 duration-200">
            {BRANDS.map((brand) => (
              <button
                key={brand}
                onClick={() => handleBrandSelect(brand)}
                className="w-full text-left px-5 py-3 hover:bg-surface transition-colors flex items-center justify-between group"
              >
                <span className={`font-serif text-sm ${selectedModel.brand === brand ? 'text-sage italic' : 'text-muted group-hover:text-text'}`}>
                  {brand}
                </span>
              </button>
            ))}
            <div className="border-t border-border mt-1 pt-1">
                 <button 
                    onClick={() => { setIsDropdownOpen(false); setIsAdvancedOpen(true); }}
                    className="w-full text-left px-5 py-3 text-[10px] uppercase tracking-widest text-muted hover:text-sage hover:bg-surface transition-colors"
                 >
                    Advanced View
                 </button>
            </div>
          </div>
        )}
      </div>

      {/* 2. ADVANCED PANEL */}
      {isAdvancedOpen && (
        <>
          <div className="fixed inset-0 z-40 bg-background/50 backdrop-blur-sm" onClick={() => setIsAdvancedOpen(false)} />

          <div 
            ref={advancedRef}
            className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full max-w-lg bg-background border border-border shadow-2xl z-50 flex flex-col max-h-[80vh]"
          >
            <div className="flex items-center justify-between px-6 py-4 border-b border-border bg-surface">
                <span className="font-serif italic text-lg text-text">Select Architecture</span>
                <button onClick={() => setIsAdvancedOpen(false)} className="text-muted hover:text-text transition-colors">
                    Close
                </button>
            </div>

            <div className="overflow-y-auto p-6 space-y-8">
                {(Object.entries(groupedModels) as [string, TargetModel[]][]).map(([provider, models]) => (
                    <div key={provider}>
                        <div className="mb-3 text-[10px] uppercase tracking-[0.2em] text-sage font-semibold">
                            {provider}
                        </div>
                        <div className="grid gap-2">
                            {models.map(model => (
                                <button
                                    key={model.id}
                                    onClick={() => { onSelect(model); setIsAdvancedOpen(false); }}
                                    className={`w-full text-left p-3 border transition-all duration-300 ${
                                        selectedModel.id === model.id 
                                            ? 'border-sage bg-sage-dim' 
                                            : 'border-border hover:border-muted hover:bg-surface'
                                    }`}
                                >
                                    <div className="flex items-center justify-between mb-1">
                                        <span className={`font-serif text-sm ${selectedModel.id === model.id ? 'text-sage' : 'text-text'}`}>
                                            {model.name}
                                        </span>
                                        {selectedModel.id === model.id && <Check size={12} className="text-sage" />}
                                    </div>
                                    <div className="text-xs text-muted font-sans line-clamp-1">
                                        {model.description}
                                    </div>
                                </button>
                            ))}
                        </div>
                    </div>
                ))}
            </div>
          </div>
        </>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Copy, Check, Save, Sparkles, Loader2, ExternalLink, ArrowRight, RefreshCcw } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { TARGET_MODELS } from '../constants';

interface OutputAreaProps {
  prompt: string;
  explanation?: string;
  onChange: (text: string) => void;
  targetModelName: string;
  onOptimize: () => void;
  isLoading: boolean;
  isDeepMode: boolean;
  generationId?: number;
}

export const OutputArea: React.FC<OutputAreaProps> = ({ 
  prompt, 
  explanation, 
  onChange, 
  targetModelName,
  onOptimize,
  isLoading,
  isDeepMode,
  generationId = 0
}) => {
  const [copiedPrompt, setCopiedPrompt] = useState(false);
  const [isPreviewMode, setIsPreviewMode] = useState(true);

  // Find the full model object to access sources
  const currentModel = TARGET_MODELS.find(m => m.name === targetModelName);

  const handleCopyPrompt = async () => {
    await navigator.clipboard.writeText(prompt);
    setCopiedPrompt(true);
    setTimeout(() => setCopiedPrompt(false), 2000);
  };

  const handleDownload = () => {
    if (!prompt.trim()) return;
    const dateStr = new Date().toISOString().slice(0, 10);
    const fileName = `ericmartin-prompt-${dateStr}.txt`;
    const blob = new Blob([prompt], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="flex flex-col flex-1 w-full pt-8 h-full animate-in">

      {/* Header / Meta */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end mb-6 border-b border-border pb-4 gap-4">
        <div>
            <h3 className="font-serif italic text-2xl text-text mb-2">Operational Syntax</h3>
            <div className="flex items-center gap-3 text-xs text-muted font-sans">
                <span className="uppercase tracking-widest">Target:</span>
                <span className="text-sage font-medium">{targetModelName}</span>
                <span className="text-border">|</span>
                <span className="uppercase tracking-widest">{isDeepMode ? 'Deep Analysis' : 'Fast Mode'}</span>
            </div>
        </div>

        <div className="flex items-center gap-6">
             <button
                onClick={onOptimize}
                disabled={isLoading}
                className="text-[10px] uppercase tracking-widest font-semibold text-muted hover:text-sage transition-colors flex items-center gap-2"
            >
                {isLoading ? <Loader2 size={12} className="animate-spin" /> : <RefreshCcw size={12} />}
                <span>Regenerate</span>
            </button>

            <button
                onClick={() => setIsPreviewMode(!isPreviewMode)}
                className="text-[10px] uppercase tracking-widest font-semibold text-muted hover:text-text transition-colors"
            >
                {isPreviewMode ? 'View Raw' : 'View Preview'}
            </button>

            <button 
                onClick={handleCopyPrompt}
                className="text-[10px] uppercase tracking-widest font-semibold text-sage hover:text-white transition-colors flex items-center gap-2"
            >
                {copiedPrompt ? <Check size={12} /> : <Copy size={12} />}
                <span>Copy to Clipboard</span>
            </button>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-8 flex-1 min-h-[500px]">

          {/* Main Content (Prompt) */}
          <div className="flex-1 flex flex-col">
            <div className={`flex-1 relative border border-border bg-surface/50 p-8 overflow-hidden transition-all duration-500 ${isDeepMode ? 'border-sage/20' : ''}`}>
                 {/* Decorative Line */}
                 <div className="absolute top-0 left-0 w-full h-0.5 bg-gradient-to-r from-sage to-transparent opacity-50"></div>

                 <div className="h-full w-full overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-border scrollbar-track-transparent">
                    {isPreviewMode ? (
                        <div className="prose prose-invert prose-p:font-light prose-p:leading-loose prose-headings:font-serif prose-headings:font-normal prose-code:text-sage prose-pre:bg-background prose-pre:border prose-pre:border-border max-w-none">
                            <ReactMarkdown>{prompt}</ReactMarkdown>
                        </div>
                    ) : (
                        <textarea
                            value={prompt}
                            onChange={(e) => onChange(e.target.value)}
                            className="w-full h-full bg-transparent text-text font-mono text-sm leading-relaxed resize-none focus:outline-none"
                            spellCheck={false}
                        />
                    )}
                 </div>
            </div>

            {/* Action Footer for Main Content */}
            <div className="mt-4 flex justify-between items-center">
                 <div className="flex gap-4">
                     {currentModel?.sources?.map((source, i) => (
                         <a key={i} href={source.url} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1 text-[10px] text-muted hover:text-sage transition-colors uppercase tracking-wider">
                             Documentation <ExternalLink size={8} />
                         </a>
                     ))}
                 </div>
                 <button onClick={handleDownload} className="text-muted hover:text-text transition-colors">
                     <Save size={14} />
                 </button>
            </div>
          </div>

          {/* Sidebar (Explanation) */}
          {explanation && (
              <div className="lg:w-80 shrink-0 border-l border-border pl-8 py-2 flex flex-col">
                  <h4 className="font-serif italic text-lg text-text mb-4">Analysis</h4>
                  <div className="text-sm font-light text-muted leading-relaxed space-y-4">
                      <ReactMarkdown 
                        components={{
                            p: ({node, ...props}) => <p className="mb-4" {...props} />,
                            strong: ({node, ...props}) => <span className="text-sage font-medium" {...props} />
                        }}
                      >
                          {explanation}
                      </ReactMarkdown>
                  </div>

                  <div className="mt-auto pt-8 border-t border-border/50">
                      <div className="text-[10px] uppercase tracking-widest text-muted mb-2">System Status</div>
                      <div className="flex items-center gap-2 text-xs text-sage">
                          <div className="w-1.5 h-1.5 bg-sage rounded-full"></div>
                          <span>Optimization Complete</span>
                      </div>
                  </div>
              </div>
          )}
      </div>
    </div>
  );
};

